el.typeControls?.addEventListener('input',e=>{let input=e.target.closest('[data-extra]');if(!input||!state.active)return;state.extras[input.dataset.extra]=Number(input.value);let v=$('#extra-'+input.dataset.extra+'-value');if(v)v.textContent=input.value+(input.dataset.unit||'');applyControls()});$('#copyCode').addEventListener('click',()=>{if(state.active){let variant=el.copyVariant?.value||state.tab;state.tab=variant;copyText(code(variant),'تم نسخ '+variant);mark(state.active.id)}});$('#copyAll').addEventListener('click',()=>{if(state.active){copyText(['HTML','CSS','JS','React','Tailwind'].map(t=>`/* ${t} */\n${code(t)}`).join('\n\n'),'تم نسخ جميع الصيغ');mark(state.active.id)}});$('#resetControls').addEventListener('click',()=>{if(!state.active)return;state.controls=baseControls(state.active);state.extras=baseExtras(state.active);updateControls();renderTypeControls(state.active);el.preview.innerHTML=state.active.code.html;el.preview.dataset.liveCategory=state.active.category;applyControls();setPreviewState('default');bindInteractivePreviews(el.preview);setDrawerPreviewActive(false);toast('تمت إعادة الضبط')});
const cmap={cColor:'color',cBg:'bg',cRadius:'radius',cPadding:'padding',cFont:'font',cShadow:'shadow',cGlow:'glow',cScale:'scale',cSpeed:'speed'};Object.keys(cmap).forEach(id=>$('#'+id).addEventListener('input',e=>{state.controls[cmap[id]]=e.target.type==='range'?Number(e.target.value):e.target.value;updateControls();applyControls()}));$('#addCollection').addEventListener('click',()=>{if(!state.active)return;let n=prompt('اسم المجموعة:','أفكار جديدة');if(!n)return;state.collections[n]=state.collections[n]||[];if(!state.collections[n].includes(state.active.id))state.collections[n].push(state.active.id);persist();header();toast(`تم الحفظ في ${n}`)});
